const normalize = text => text.replace(/\r\n/g, '\n');
const pending = [];
for (const change of changes) {
  const file = path.resolve(process.cwd(), change.file);
  if (!fs.existsSync(file)) throw new Error('No se encuentra ' + change.file + '. Ejecuta el script desde la carpeta que contiene App.tsx.');
  const original = fs.readFileSync(file, 'utf8');
  const current = normalize(original);
  if (current === change.after) continue;
  if (current !== change.before) throw new Error('El archivo ' + change.file + ' tiene otros cambios. No se ha modificado ningun archivo. Comparte este mensaje antes de continuar.');
  const ending = original.includes('\r\n') ? '\r\n' : '\n';
  pending.push({ file, content: change.after.replace(/\n/g, ending) });
}
for (const item of pending) fs.writeFileSync(item.file, item.content, 'utf8');
console.log('Limpieza final completada: ' + pending.length + ' archivos actualizados. Limpieza de estilos, coordenadas, formatos y funciones sin uso.');
